package practice
import ("testing";"reflect";)

func TestContract(t *testing.T){
for repeat:=0;repeat<40;repeat++{a:=[]int{3,-2,0,7};b:=Squares(a);if !reflect.DeepEqual(b,[]int{9,4,0,49}){t.Fatal(b)};b[0]=1;if a[0]!=3{t.Fatal("shared")}};if len(Squares(nil))!=0{t.Fatal("empty")}
}

