import re
def rollout(existing,generated):
    def checked(values):
        if not isinstance(values,list):raise ValueError('list required')
        if any(not isinstance(x,str) or not re.fullmatch(r'[0-9A-HJKMNP-TV-Z]{26}',x) for x in values):raise ValueError('invalid block ID')
        if len(set(values))!=len(values):raise ValueError('duplicate block ID')
        return set(values)
    old,new=checked(existing),checked(generated)
    if old&new:raise ValueError('existing block collision')
    return {'install':sorted(new),'rollback_remove':sorted(new),'preserve':sorted(old)}
