import zipfile,io,tempfile,shutil
from pathlib import Path,PurePosixPath
def unpack(data,dest,limit=1048576):
 dest=Path(dest)
 if dest.exists():raise ValueError('exists')
 entries=[];seen=set();total=0
 with zipfile.ZipFile(io.BytesIO(data))as z:
  for info in z.infolist():
   name=info.filename;parts=name.split('/')
   if info.is_dir():continue
   if not name or name.startswith('/')or '\\'in name or ':'in name or any(x in ('','.','..')for x in parts):raise ValueError('path')
   if name in seen or (info.external_attr>>16)&0o170000==0o120000:raise ValueError('duplicate or symlink')
   seen.add(name);total+=info.file_size
   if total>limit:raise ValueError('size')
   entries.append((name,z.read(info)))
 for name in seen:
  if any('/'.join(name.split('/')[:i])in seen for i in range(1,len(name.split('/')))):raise ValueError('file directory collision')
 dest.parent.mkdir(parents=True,exist_ok=True)
 with tempfile.TemporaryDirectory(dir=dest.parent)as temp:
  stage=Path(temp)/'tree';stage.mkdir()
  for name,raw in entries:
   p=stage/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
  stage.rename(dest)
 return len(entries)
```

