import csv,io,json,ipaddress,os,tempfile
from pathlib import Path
def compile_inventory(csv_text,dest):
 reader=csv.DictReader(io.StringIO(csv_text))
 if reader.fieldnames!=['name','address','groups']:raise ValueError('header')
 hosts={}
 for row in reader:
  if None in row or any(value is None for value in row.values()):raise ValueError('columns')
  name=row['name'].strip()
  if not name or name in hosts:raise ValueError('name')
  address=str(ipaddress.ip_address(row['address'].strip()))
  groups=sorted(set(g.strip()for g in row['groups'].split(';')if g.strip()))
  hosts[name]={'address':address,'groups':groups}
 result={'hosts':dict(sorted(hosts.items()))};dest=Path(dest);dest.parent.mkdir(parents=True,exist_ok=True)
 fd,temp=tempfile.mkstemp(dir=dest.parent,prefix='.inventory-')
 try:
  with os.fdopen(fd,'w',encoding='utf-8')as f:json.dump(result,f,sort_keys=True);f.flush();os.fsync(f.fileno())
  os.replace(temp,dest)
 finally:
  if os.path.exists(temp):os.unlink(temp)
 return result
```

