import subprocess,threading,os,signal

def run_bounded(argv,timeout,max_bytes):
    if not isinstance(argv,list) or not argv or not all(isinstance(x,str) for x in argv):raise ValueError('argv must be a nonempty string list')
    if isinstance(timeout,bool) or not isinstance(timeout,(int,float)) or not 0.01<=timeout<=30:raise ValueError('invalid timeout')
    if isinstance(max_bytes,bool) or not isinstance(max_bytes,int) or not 1<=max_bytes<=1048576:raise ValueError('invalid capture bound')
    proc=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True,bufsize=0)
    captured={'stdout':bytearray(),'stderr':bytearray()};totals={'stdout':0,'stderr':0}
    def pump(name,stream):
        while True:
            chunk=stream.read(65536)
            if not chunk:break
            totals[name]+=len(chunk)
            remaining=max_bytes-len(captured[name])
            if remaining>0:captured[name].extend(chunk[:remaining])
    readers=[threading.Thread(target=pump,args=(name,getattr(proc,name)),daemon=True) for name in ('stdout','stderr')]
    for reader in readers:reader.start()
    timed_out=False
    try:proc.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        timed_out=True
        try:os.killpg(proc.pid,signal.SIGTERM)
        except ProcessLookupError:pass
        try:proc.wait(timeout=0.15)
        except subprocess.TimeoutExpired:
            try:os.killpg(proc.pid,signal.SIGKILL)
            except ProcessLookupError:pass
            proc.wait()
    for reader in readers:reader.join(timeout=2)
    if any(reader.is_alive() for reader in readers):raise RuntimeError('pipe reader did not stop')
    decode=lambda value:bytes(value).decode('utf-8','replace')
    return {'returncode':proc.returncode,'stdout':decode(captured['stdout']),'stderr':decode(captured['stderr']),'stdout_total':totals['stdout'],'stderr_total':totals['stderr'],'truncated':totals['stdout']>max_bytes or totals['stderr']>max_bytes,'timed_out':timed_out}
