import heapq,tempfile
from pathlib import Path
from contextlib import ExitStack
def sort_numbers(values,chunk=100):
 if type(chunk)is not int or chunk<1:raise ValueError()
 with tempfile.TemporaryDirectory()as d,ExitStack()as stack:
  files=[];part=[]
  def flush():
   if not part:return
   p=Path(d)/str(len(files));p.write_text(''.join(str(v)+'\n'for v in sorted(part)),encoding='utf-8')
   files.append(stack.enter_context(p.open(encoding='utf-8')));part.clear()
