        self.data[(self.head+self.size)%len(self.data)]=value;self.size+=1
    def pop(self):
        if not self.size:raise IndexError('empty')
        value=self.data[self.head];self.data[self.head]=None
        self.head=(self.head+1)%len(self.data);self.size-=1
        return value
