import json,re
from pathlib import Path
class Index:
 def __init__(self):self.docs={};self.words={}
 @staticmethod
 def tokens(text):return set(re.findall(r'[a-z0-9]+',text.lower()))
 def put(self,key,text):
  self.delete(key);self.docs[key]=text
  for word in self.tokens(text):self.words.setdefault(word,set()).add(key)
 def delete(self,key):
  old=self.docs.pop(key,None)
  if old is not None:
   for word in self.tokens(old):
    self.words[word].discard(key)
    if not self.words[word]:del self.words[word]
 def search(self,text):
  terms=self.tokens(text)
  if not terms:return []
  groups=[self.words.get(t,set())for t in terms]
  return sorted(set.intersection(*map(set,groups)))
 def save(self,path):Path(path).write_text(json.dumps(self.docs,sort_keys=True),encoding='utf-8')
 @classmethod
 def load(cls,path):
  out=cls()
  for key,text in json.loads(Path(path).read_text(encoding='utf-8')).items():out.put(key,text)
  return out
```

