import json,base64
def encode(x):
    t=type(x);name=t.__name__
    if t in(type(None),bool,int,str):v=x
    elif t in(list,tuple):v=[encode(i)for i in x]
    elif t is bytes:v=base64.b64encode(x).decode('ascii')
    elif t is dict:
        if any(type(k)is not str for k in x):raise TypeError('key')
        v=[[k,encode(val)]for k,val in x.items()]
    else:raise TypeError('type')
    return {'t':name,'v':v}
def decode(node):
    if type(node)is not dict or set(node)!= {'t','v'}:raise ValueError('node')
    tag,value=node['t'],node['v']
    if type(tag)is not str:raise ValueError('tag type')
    types={'NoneType':type(None),'bool':bool,'int':int,'str':str}
    if tag in types:
        if type(value)is not types[tag]:raise ValueError('scalar')
        return value
    if tag in('list','tuple'):
        if type(value)is not list:raise ValueError('sequence')
        seq=[decode(x)for x in value];return tuple(seq)if tag=='tuple'else seq
    if tag=='bytes':
        if type(value)is not str:raise ValueError('bytes')
        try:return base64.b64decode(value,validate=True)
        except Exception as e:raise ValueError('base64')from e
    if tag=='dict':
        if type(value)is not list:raise ValueError('dict')
        out={}
        for pair in value:
            if type(pair)is not list or len(pair)!=2 or type(pair[0])is not str or pair[0]in out:raise ValueError('pair')
            out[pair[0]]=decode(pair[1])
        return out
    raise ValueError('tag')
def dumps(value):return json.dumps(encode(value),ensure_ascii=False)
def loads(text):return decode(json.loads(text))
