```yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ .Release.Name }}
  namespace: {{ .Release.Namespace }}
spec:
  replicas: {{ .Values.replicas }}
  selector:
    matchLabels: {app: {{ .Release.Name | quote }}}
  template:
    metadata:
      labels: {app: {{ .Release.Name | quote }}}
    spec:
      automountServiceAccountToken: false
      containers:
      - name: app
        image: {{ .Values.image | quote }}
        resources:
          requests: {cpu: {{ printf "%dm" (int .Values.cpuMilli) | quote }}, memory: {{ printf "%dMi" (int .Values.memoryMi) | quote }}}
          limits: {cpu: {{ printf "%dm" (mul 2 (int .Values.cpuMilli)) | quote }}, memory: {{ printf "%dMi" (mul 2 (int .Values.memoryMi)) | quote }}}
        securityContext:
          runAsNonRoot: true
          allowPrivilegeEscalation: false
          capabilities: {drop: [ALL]}
{{ if .Values.credentialsSecret }}
        envFrom:
        - secretRef:
            name: {{ .Values.credentialsSecret | quote }}
{{ end }}
{{ if eq .Values.profile "prod" }}
---
apiVersion: policy/v1
kind: PodDisruptionBudget
metadata:
  name: {{ .Release.Name }}
  namespace: {{ .Release.Namespace }}
spec:
  minAvailable: 1
  selector:
    matchLabels: {app: {{ .Release.Name | quote }}}
{{ end }}
```

保留开箱可渲染的dev默认配置，但profile=prod必须显式满足：registry.example.com镜像完整sha256摘要、2..5副本、CPU请求250..1000m、内存请求256..1024Mi、非空DNS形式credentialsSecret。dev基础边界是副本1..5、CPU100..1000m、内存128..1024Mi。始终禁止未知参数及错误类型；两个profile都关闭令牌自动挂载、非root、不允许提权/drop ALL。limits为各requests两倍；Secret只引用、不创建；prod有PDB(minAvailable1)，dev没有。交付schema和资源模板，证明单改profile为prod会被拒绝，完整配置才通过。只验证策略声明，不验证镜像、Secret或实际可用性。

