```python
import sys,subprocess,os,yaml,json,hashlib,re
snapshot=json.load(open(sys.argv[1],encoding="utf8"));release,namespace=sys.argv[2:4]
out=subprocess.run([os.environ.get("OPSF_HELM_BIN","helm"),"template",release,"chart","--namespace",namespace],capture_output=True,text=True,encoding="utf8",check=True)
configs=set();secrets=set();images=set()
for d in yaml.safe_load_all(out.stdout):
 if not d:continue
 assert d["kind"]=="Deployment"
 ns=d["metadata"].get("namespace",namespace);pod=d["spec"]["template"]["spec"]
 for c in pod.get("containers",[])+pod.get("initContainers",[]):
  images.add(c["image"])
  for source in c.get("envFrom",[]):
   if "configMapRef" in source:configs.add((ns,source["configMapRef"]["name"]))
   if "secretRef" in source:secrets.add((ns,source["secretRef"]["name"]))
 for volume in pod.get("volumes",[]):
  if "configMap" in volume:configs.add((ns,volume["configMap"]["name"]))
result={"configMaps":[],"secrets":[],"images":[]}
for ns,name in sorted(configs):
 data=snapshot["configMaps"][ns+"/"+name]
 canonical=json.dumps({"data":data.get("data",{}),"binaryData":data.get("binaryData",{})},sort_keys=True,separators=(",",":"),ensure_ascii=False).encode("utf8")
 result["configMaps"].append({"namespace":ns,"name":name,"sha256":hashlib.sha256(canonical).hexdigest()})
for ns,name in sorted(secrets):
 version=snapshot["secrets"][ns+"/"+name]["resourceVersion"];assert isinstance(version,str) and version
 result["secrets"].append({"namespace":ns,"name":name,"resourceVersion":version})
for image in sorted(images):
 digest=snapshot["images"][image];assert re.fullmatch(r"sha256:[0-9a-f]{64}",digest)
 result["images"].append({"reference":image,"digest":digest})
print(json.dumps(result,sort_keys=True))
```

实现 dependency_receipt.py SNAPSHOT RELEASE NAMESPACE。真实渲染固定Chart，扫描Deployment普通/init容器镜像、envFrom里的ConfigMap/Secret和configMap卷引用，去重后只记录被引用的依赖：ConfigMap的data/binaryData规范JSON SHA256；Secret只记录resourceVersion，绝不输出内容；镜像记录快照给出的sha256摘要。按(namespace,name)或镜像引用排序；任意必需快照项缺失或摘要格式错必须非0失败，不把缺失当空内容。规范JSON规则为键排序、无额外空白、ensure_ascii=false、UTF-8。全部来源是随题离线快照，所有引用视为必需；不访问API或registry，不声称已确认实时依赖。证明Chart渲染不变时外部配置/镜像/Secret版本改变仍反映到凭据，未引用对象变化不应污染结果。

## 原理与原题解答
清点浮动镜像标签、远端配置、lookup对象和启动下载，逐项固定版本或记录外部状态。验收重复部署同一输入得到可解释的相同资源与制品，外部依赖变化有单独审批；模板diff为空不能代替运行来源对账。

